command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="24bb8722c06b302f6a6b9c00aad34293a38be0d0";$candidate="a08e32788bdcd5d33da31e0c413803f30e548b92";$branch="work/unc-network-copy-move-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "UNC final GUI fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before UNC final GUI"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "UNC final GUI candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-unc-final-gui-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "UNC final GUI worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "UNC final GUI diff check failed"}
 & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
 if($LASTEXITCODE -ne 0){throw "UNC final GUI FAST failed"}
 & .\build.bat Release
 if($LASTEXITCODE -ne 0){throw "UNC final GUI Release build failed"}
 & python -X utf8 tools\winui\run_checks.py gui --area unc-copy-move --configuration Release
 if($LASTEXITCODE -ne 0){throw "UNC final focused GUI failed"}
 Write-Host "UNC_COPY_MOVE_FINAL_DIFF_CHECK=PASS"
 Write-Host "UNC_COPY_MOVE_FINAL_FAST=PASS"
 Write-Host "UNC_COPY_MOVE_FINAL_RELEASE_BUILD=PASS"
 Write-Host "UNC_COPY_MOVE_FINAL_UIA_GUI=PASS"
 Write-Host "UNC_COPY_MOVE_REUSED_M22_RELEASE_RUN=37553699165"
 Write-Host "UNC_COPY_MOVE_PHYSICAL_SMB=NOT_RUN_NO_OWNED_SHARE"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
